import{_ as e,a0 as T,w as s,s as u,ao as p,I as l,x as r,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy | LCTT x X-CMD","titleTemplate":false,"description":"五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20151104 Optimize Web Delivery with these Open Source Tools","title":"五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy","tag":"201603","desc":""},"relativePath":"201603/20151104 Optimize Web Delivery with these Open Source Tools.md","filePath":"[post].md"}'),a={name:"201603/20151104 Optimize Web Delivery with these Open Source Tools.md"};function P(d,i,S,y,x,b){const o=T("Link");return s(),u("div",null,[i[36]||(i[36]=p('<h1 id="五大開源-web-代理軟件橫向比較-squid、privoxy、varnish、polipo、tinyproxy" tabindex="-1">五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy <a class="header-anchor" href="#五大開源-web-代理軟件橫向比較-squid、privoxy、varnish、polipo、tinyproxy" aria-label="Permalink to “五大開源 Web 代理軟件橫向比較：Squid、Privoxy、Varnish、Polipo、Tinyproxy”">​</a></h1><p>Web 代理軟件轉發 HTTP 請求時並不會改變數據流量。它們可以配置成透明代理，而無需客户端配置。它們還可以作為反向代理放在網站的前端；這樣緩存服務器可以為一台或多台 web 服務器提供無限量的用户服務。</p><p>網站代理功能多樣，有着寬泛的用途：從緩存頁面、DNS 和其他查詢，到加速 web 服務器響應、降低帶寬消耗。代理軟件廣泛用於大型高訪問量的網站，比如紐約時報、衞報， 以及社交媒體網站如 Twitter、Facebook 和 Wikipedia。</p><p>頁面緩存已經成為優化單位時間內所能吞吐的數據量的至關重要的機制。好的 Web 緩存還能降低延遲，儘可能快地響應頁面，讓終端用户不至於因等待內容的時間過久而失去耐心。它們還能將頻繁訪問的內容緩存起來以節省帶寬。如果你需要降低服務器負載並改善網站內容響應速度，那緩存軟件能帶來的好處就絕對值得探索一番。</p><p>為深入探查 Linux 下可用的相關軟件的質量，我列出了下邊5個優秀的開源 web 代理工具。它們中有些功能完備強大，也有幾個只需很低的資源就能運行。</p><h3 id="squid" tabindex="-1">Squid <a class="header-anchor" href="#squid" aria-label="Permalink to “Squid”">​</a></h3><p>Squid 是一個高性能、開源的代理緩存服務器和 Web 緩存進程，支持 FTP、Internet Gopher、HTTPS 和 SSL 等多種協議。它通過一個非阻塞的、I/O 事件驅動的單一進程處理所有的 IPV4 或 IPV6 協議請求。</p><p>Squid 由一個主服務程序 squid，和 DNS 查詢程序 dnsserver，另外還有一些可選的請求重寫、執行認證程序組件，及一些管理和客户端工具構成。</p><p>Squid 提供了豐富的訪問控制、認證和日誌環境， 用於開發 web 代理和內容服務網站應用。</p><p>其特性包括：</p><ul><li>Web 代理： <ul><li>通過緩存來降低訪問時間和帶寬使用</li><li>將元數據和訪問特別頻繁的對象緩存到內存中</li><li>緩存 DNS 查詢</li><li>支持非阻塞的 DNS 查詢</li><li>實現了失敗請求的未果緩存</li></ul></li><li>Squid 緩存可架設為層次結構，或網狀結構以節省額外的帶寬</li><li>通過廣泛的訪問控制來執行網站訪問策略</li><li>隱匿請求，如禁用或修改客户端 HTTP 請求頭特定屬性</li><li>反向代理</li><li>媒體範圍（media-range）限制</li><li>支持 SSL</li><li>支持 IPv6</li><li>錯誤頁面的本地化 - Squid 可以根據訪問者的語言選項對每個請求展示本地化的錯誤頁面</li><li>連接固定（Connection Pinning ）（用於 NTLM Auth Passthrough） - 一種允許 Web 服務器通過 Web 代理使用Microsoft NTLM 安全認證替代 HTTP 標準認證的方案</li><li>支持服務質量 (QoS, Quality of Service) 流 <ul><li>選擇一個 TOS/Diffserv 值來標記本地命中</li><li>選擇一個 TOS/Diffserv 值來標記對端命中</li><li>選擇性地僅標記同級或上級請求</li><li>允許任意發往客户端的 HTTP 響應保持由遠程服務器處響應的 TOS 值</li><li>對收到的遠程服務器的 TOS 值，在複製之前對指定位進行掩碼操作，再發送到客户端</li></ul></li><li>SSL Bump (用於 HTTPS 過濾和適配) - Squid-in-the-middle，在 CONNECT 方式的 SSL 隧道中，用配置化的客户端和服務器端證書，對流量進行解密和加密</li><li>支持適配模組</li><li>ICAP 旁路和重試增強 - 通過完全的旁路和動態鏈式路由擴展 ICAP，來處理多多個適應性服務。</li><li>支持 ICY 流式協議 - 俗稱 SHOUTcast 多媒體流</li><li>動態 SSL 證書生成</li><li>支持 ICAP 協議 (Internet Content Adaptation Protocol)</li><li>完整的請求日誌記錄</li><li>匿名連接</li></ul><p>--</p>',12)),l("ul",null,[l("li",null,[i[1]||(i[1]=r("網站: ",-1)),n(o,{href:"http://www.squid-cache.org/"},{default:t(()=>[...i[0]||(i[0]=[r("www.squid-cache.org",-1)])]),_:1})]),i[2]||(i[2]=l("li",null,"開發: 美國國家應用網絡研究實驗室(NLANR)和網絡志願者",-1)),i[3]||(i[3]=l("li",null,"授權: GNU GPL v2",-1)),i[4]||(i[4]=l("li",null,"版本號: 4.0.1",-1))]),i[37]||(i[37]=p('<h3 id="privoxy" tabindex="-1">Privoxy <a class="header-anchor" href="#privoxy" aria-label="Permalink to “Privoxy”">​</a></h3><p>Privoxy (Privacy Enhancing Proxy) 是一個非緩存類 Web 代理軟件，它自帶的高級過濾功能可以用來增強隱私保護、修改頁面內容和 HTTP 頭部信息、訪問控制，以及去除廣告和其它招人反感的互聯網垃圾。Privoxy 的配置非常靈活，能充分定製已滿足各種各樣的需求和偏好。它支持單機和多用户網絡兩種模式。</p><p>Privoxy 使用 action 規則來處理瀏覽器和遠程站點間的數據流。</p><p>其特性包括：</p><ul><li>高度配置化——可以完全定製你的配置</li><li>廣告攔截</li><li>Cookie 管理</li><li>支持“Connection: keep-alive”。可以無視客户端配置而保持外發的持久連接</li><li>支持 IPv6</li><li>標籤化（Tagging），允許按照客户端和服務器的請求頭進行處理</li><li>作為攔截（intercepting）代理器運行</li><li>巧妙的動作（action）和過濾機制用來處理服務器和客户端的 HTTP 頭部</li><li>可以與其他代理軟件鏈式使用</li><li>整合了基於瀏覽器的配置和控制工具，能在線跟蹤規則和過濾效果，可遠程開關</li><li>頁面過濾（文本替換、根據尺寸大小刪除廣告欄, 隱藏的“web-bugs”元素和 HTML 容錯等）</li><li>模組化的配置使得標準配置和用户配置可以存放於不同文件中，這樣安裝更新就不會覆蓋用户的個性化設置</li><li>配置文件支持 Perl 兼容的正則表達式，以及更為精妙和靈活的配置語法</li><li>GIF 去動畫</li><li>旁路處理大量點擊跟蹤（click-tracking）腳本（避免腳本重定向）</li><li>大多數代理生成的頁面（例如 &quot;訪問受限&quot; 頁面）可由用户自定義HTML模板</li><li>自動監測配置文件的修改並重新讀取</li><li>大多數功能可以基於每個站點或每個 URL 位置來進行控制</li></ul><p>--</p>',6)),l("ul",null,[l("li",null,[i[6]||(i[6]=r("網站: ",-1)),n(o,{href:"http://www.privoxy.org/"},{default:t(()=>[...i[5]||(i[5]=[r("www.privoxy.org",-1)])]),_:1})]),i[7]||(i[7]=l("li",null,"開發: Fabian Keil（開發領導者）, David Schmidt, 和眾多其他貢獻者",-1)),i[8]||(i[8]=l("li",null,"授權: GNU GPL v2",-1)),i[9]||(i[9]=l("li",null,"版本號: 3.4.2",-1))]),i[38]||(i[38]=p('<h3 id="varnish-cache" tabindex="-1">Varnish Cache <a class="header-anchor" href="#varnish-cache" aria-label="Permalink to “Varnish Cache”">​</a></h3><p>Varnish Cache 是一個為性能和靈活性而生的 web 加速器。它新穎的架構設計能帶來顯著的性能提升。根據你的架構，通常情況下它能加速響應速度300-1000倍。Varnish 將頁面存儲到內存，這樣 web 服務器就無需重複地創建相同的頁面，只需要在頁面發生變化後重新生成。頁面內容直接從內存中訪問，當然比其他方式更快。</p><p>此外 Varnish 能大大提升響應 web 頁面的速度，用在任何應用服務器上都能使網站訪問速度大幅度地提升。</p><p>按經驗，Varnish Cache 比較經濟的配置是1-16GB內存+ SSD 固態硬盤。</p><p>其特性包括：</p><ul><li>新穎的設計</li><li>VCL - 非常靈活的配置語言。VCL 配置會轉換成 C，然後編譯、加載、運行，靈活且高效</li><li>能使用 round-robin 輪詢和隨機分發兩種方式來負載均衡，兩種方式下後端服務器都可以設置權重</li><li>基於 DNS、隨機、散列和客户端 IP 的分發器（Director）</li><li>多台後端主機間的負載均衡</li><li>支持 Edge Side Includes，包括拼裝壓縮後的 ESI 片段</li><li>重度多線程併發</li><li>URL 重寫</li><li>單 Varnish 能夠緩存多個虛擬主機</li><li>日誌數據存儲在共享內存中</li><li>基本的後端服務器健康檢查</li><li>優雅地處理後端服務器“掛掉”</li><li>命令列界面的管理控制台</li><li>使用內聯 C 語言來擴展 Varnish</li><li>可以與 Apache 用在相同的系統上</li><li>單個系統可運行多個 Varnish</li><li>支持 HAProxy 代理協議。該協議在每個收到的 TCP 請求——例如 SSL 終止過程中——附加一小段 http 頭信息，以記錄客户端的真實地址</li><li>冷熱 VCL 狀態</li><li>可以用名為 VMOD 的 Varnish 模組來提供插件擴展</li><li>通過 VMOD 定義後端主機</li><li>Gzip 壓縮及解壓</li><li>HTTP 流的通過和獲取</li><li>神聖模式和優雅模式。用 Varnish 作為負載均衡器，神聖模式下可以將不穩定的後端服務器在一段時間內打入黑名單，阻止它們繼續提供流量服務。優雅模式允許 Varnish 在獲取不到後端服務器狀態良好的響應時，提供已過期版本的頁面或其它內容。</li><li>實驗性支持持久化存儲，無需 LRU 緩存淘汰</li></ul><p>--</p>',7)),l("ul",null,[l("li",null,[i[11]||(i[11]=r("網站: ",-1)),n(o,{href:"https://www.varnish-cache.org/"},{default:t(()=>[...i[10]||(i[10]=[r("www.varnish-cache.org",-1)])]),_:1})]),i[12]||(i[12]=l("li",null,"開發: Varnish Software",-1)),i[13]||(i[13]=l("li",null,"授權: FreeBSD",-1)),i[14]||(i[14]=l("li",null,"版本號: 4.1.0",-1))]),i[39]||(i[39]=p('<h3 id="polipo" tabindex="-1">Polipo <a class="header-anchor" href="#polipo" aria-label="Permalink to “Polipo”">​</a></h3><p>Polipo 是一個開源的 HTTP 緩存代理，只需要非常低的資源開銷。</p><p>它監聽來自瀏覽器的 web 頁面請求，轉發到 web 服務器，然後將服務器的響應轉發到瀏覽器。在此過程中，它能優化和整形網絡流量。從本質來講 Polipo 與 WWWOFFLE 很相似，但其實現技術更接近於 Squid。</p><p>Polipo 最開始的目標是作為一個兼容 HTTP/1.1 的代理，理論它能在任何兼容 HTTP/1.1 或更早的 HTTP/1.0 的站點上運行。</p><p>其特性包括：</p><ul><li>HTTP 1.1、IPv4 &amp; IPv6、流量過濾和隱私保護增強</li><li>如確認遠程服務器支持的話，則無論收到的請求是管道處理過的還是在多個連接上同時收到的，都使用 HTTP/1.1 管道（pipelining）</li><li>下載被中斷時緩存起始部分，當需要續傳時用區間（Range）請求來完成下載</li><li>將 HTTP/1.0 的客户端請求升級為 HTTP/1.1，然後按照客户端支持的級別進行升級或降級後回覆</li><li>全面支持 IPv6 （作用域（鏈路本地）地址除外）</li><li>作為 IPv4 和 IPv6 網絡的網橋</li><li>內容過濾</li><li>能使用 Poor Man 多路複用技術（Poor Man&#39;s Multiplexing）降低延遲</li><li>支持 SOCKS 4 和 SOCKS 5 協議</li><li>HTTPS 代理</li><li>扮演透明代理的角色</li><li>可以與 Privoxy 或 tor 一起運行</li></ul><p>--</p>',7)),l("ul",null,[l("li",null,[i[16]||(i[16]=r("網站: ",-1)),n(o,{href:"http://www.pps.univ-paris-diderot.fr/%7Ejch/software/polipo/"},{default:t(()=>[...i[15]||(i[15]=[r("www.pps.univ-paris-diderot.fr/~jch/software/polipo/",-1)])]),_:1})]),i[17]||(i[17]=l("li",null,"開發: Juliusz Chroboczek, Christopher Davis",-1)),i[18]||(i[18]=l("li",null,"授權: MIT License",-1)),i[19]||(i[19]=l("li",null,"版本號: 1.1.1",-1))]),i[40]||(i[40]=p('<h3 id="tinyproxy" tabindex="-1">Tinyproxy <a class="header-anchor" href="#tinyproxy" aria-label="Permalink to “Tinyproxy”">​</a></h3><p>Tinyproxy 是一個輕量級的開源 web 代理守護進程，其設計目標是快而小。它適用於需要完整 HTTP 代理特性，但系統資源又不足以運行大型代理的場景，比如嵌入式部署。</p><p>Tinyproxy 對小規模網絡非常有用，這樣的場合下大型代理會使系統資源緊張，或有安全風險。Tinyproxy 的一個關鍵特性是其緩衝連接的理念。從效果上看， Tinyproxy 對服務器的響應進行了高速緩衝，然後按照客户端能夠處理的最高速度進行響應。該特性極大的降低了網絡延滯帶來的問題。</p><p>特性：</p><ul><li>易於修改</li><li>隱匿模式 - 定義哪些 HTTP 頭允許通過，哪些又會被攔截</li><li>支持 HTTPS - Tinyproxy 允許通過 CONNECT 方法轉發 HTTPS 連接，任何情況下都不會修改數據流量</li><li>遠程監控 - 遠程訪問代理統計數據，讓你能清楚瞭解代理服務當前的忙碌狀態</li><li>平均負載監控 - 通過配置，當服務器的負載接近一定值後拒絕新連接</li><li>訪問控制 - 通過配置，僅允許指定子網或 IP 地址的訪問</li><li>安全 - 運行無需額外權限，減小了系統受到威脅的概率</li><li>基於 URL 的過濾 - 允許基於域和URL的黑白名單</li><li>透明代理 - 配置為透明代理，這樣客户端就無需任何配置</li><li>代理鏈 - 在流量出口處採用上游代理服務器，而不是直接轉發到目標服務器，創建我們所説的代理鏈</li><li>隱私特性 - 限制允許從瀏覽器收到的來自 HTTP 服務器的數據（例如 cookies），同時限制允許通過的從瀏覽器到 HTTP 服務器的數據（例如版本信息）</li><li>低開銷 - 使用 glibc 內存開銷只有2MB，CPU 負載按併發連接數線性增長（取決於網絡連接速度）。 Tinyproxy 可以運行在老舊的機器上而無需擔心性能問題。</li></ul><p>--</p>',6)),l("ul",null,[l("li",null,[i[21]||(i[21]=r("網站: ",-1)),n(o,{href:"https://banu.com/tinyproxy/"},{default:t(()=>[...i[20]||(i[20]=[r("banu.com/tinyproxy",-1)])]),_:1})]),i[22]||(i[22]=l("li",null,"開發: Robert James Kaes和其他貢獻者",-1)),i[23]||(i[23]=l("li",null,"授權: GNU GPL v2",-1)),i[24]||(i[24]=l("li",null,"版本號: 1.8.3",-1))]),i[41]||(i[41]=l("hr",null,null,-1)),l("p",null,[i[26]||(i[26]=r("via: ",-1)),n(o,{href:"http://www.linuxlinks.com/article/20151101020309690/WebDelivery.html"},{default:t(()=>[...i[25]||(i[25]=[r("http://www.linuxlinks.com/article/20151101020309690/WebDelivery.html",-1)])]),_:1})]),l("p",null,[i[29]||(i[29]=r("譯者：",-1)),n(o,{href:"https://github.com/fw8899"},{default:t(()=>[...i[27]||(i[27]=[r("fw8899",-1)])]),_:1}),i[30]||(i[30]=r(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:t(()=>[...i[28]||(i[28]=[r("wxy",-1)])]),_:1})]),l("p",null,[i[33]||(i[33]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[31]||(i[31]=[r("LCTT",-1)])]),_:1}),i[34]||(i[34]=r(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:t(()=>[...i[32]||(i[32]=[r("Linux中國",-1)])]),_:1}),i[35]||(i[35]=r(" 榮譽推出",-1))])])}const f=e(a,[["render",P]]);export{C as __pageData,f as default};
